import 'package:dart_mappable/dart_mappable.dart';

@MappableClass()
class User with UserMappable {
  final String name;
  final int age;
  const User(this.name, this.age);
}

void main() {
  final user = User('Alice', 30);
  final json = user.toJson();
  final restored = UserMapper.fromMap(json);
  print(restored);
}
